        const a = pick([0, 0.1, 0.2, 0.25, 0.3, 0.4]), b = pick([0.5, 0.6, 0.75, 0.8, 0.9]), p = +(b - a).toFixed(2);
        const I = a === 0 ? `inférieur à $${fr(b)}$` : `dans l'intervalle $[${fr(a)}\\,;${fr(b)}[$`;
